import json, subprocess, sys, collections, random
sys.path.insert(0,'/workspace/submission')
import main as entry

def bfs(adj,s):
    d=[-1]*len(adj);d[s]=0;q=collections.deque([s])
    while q:
        u=q.popleft()
        for v in adj[u]:
            if d[v]<0:d[v]=d[u]+1;q.append(v)
    return d

def topo(top):
    mode=top[0]
    if mode=='clos':
        k=top[1];scope=top[2];intra=top[3];r=k//2;T=k*r;n=k*k
        pairs=[];dom=[]
        for src in range(T):
            for dst in range(T):
                if src==dst:continue
                if not intra and src//r==dst//r:continue
                fp={src,dst}
                if src//r==dst//r:
                    for a in range(r):fp.add(T+(src//r)*r+a)
                else:
                    for a in range(r):
                        fp.add(T+(src//r)*r+a);fp.add(T+(dst//r)*r+a)
                pairs.append((src,dst,fp))
                dom.append(src if scope=='tor' else src//r)
        return n,pairs,dom
    if mode=='leaf-spine':
        l,s=top[1],top[2];n=l+s
        pairs=[];dom=[]
        for src in range(l):
            for dst in range(l):
                if src==dst:continue
                pairs.append((src,dst,{src,dst}));dom.append(src)
        return n,pairs,dom
    if mode in ('torus2d','torus3d'):
        nn=top[1];scope=top[2]
        n=nn**(2 if mode=='torus2d' else 3)
        adj=[[] for _ in range(n)]
        def nid(x,y,z=0):return (z*nn+y)*nn+x
        for z in range(nn if mode=='torus3d' else 1):
          for y in range(nn):
            for x in range(nn):
              u=nid(x,y,z)
              if mode=='torus2d':
                for dx,dy in ((1,0),(0,1)):
                  v=nid((x+dx)%nn,(y+dy)%nn)
                  adj[u].append(v);adj[v].append(u)
              else:
                for dx,dy,dz in ((1,0,0),(0,1,0),(0,0,1)):
                  v=nid((x+dx)%nn,(y+dy)%nn,(z+dz)%nn)
                  adj[u].append(v);adj[v].append(u)
        alld=[bfs(adj,s) for s in range(n)]
        pairs=[];dom=[]
        for src in range(n):
            for dst in range(n):
                if src==dst:continue
                D=alld[src][dst]
                fp={x for x in range(n) if alld[src][x]+alld[dst][x]==D}
                pairs.append((src,dst,fp))
                if scope=='host':dom.append(src)
                elif mode=='torus2d':dom.append(src//nn)
                else:dom.append(src//nn)
        return n,pairs,dom
    if mode=='dragonfly':
        g,a,h=top[1],top[2],top[3];scope=top[4];n=g*a
        adj=[[] for _ in range(n)]
        def rid(gr,r):return gr*a+r
        for gr in range(g):
            for i in range(a):
                for j in range(i+1,a):
                    u=rid(gr,i);v=rid(gr,j);adj[u].append(v);adj[v].append(u)
        for i in range(g):
            for j in range(i+1,g):
                delta=j-i
                u=rid(i,(delta-1)//h);v=rid(j,(g-delta-1)//h)
                adj[u].append(v);adj[v].append(u)
        alld=[bfs(adj,s) for s in range(n)]
        pairs=[];dom=[]
        for src in range(n):
            for dst in range(n):
                if src==dst:continue
                D=alld[src][dst]
                fp={x for x in range(n) if alld[src][x]+alld[dst][x]==D}
                pairs.append((src,dst,fp))
                if scope=='router':dom.append(src)
                elif scope=='group':dom.append(src//a)
                else:dom.append(src*g + dst//a)
        return n,pairs,dom
    if mode=='dragonfly-plus':
        g,l,s,h,dense,scope=top[1],top[2],top[3],top[4],top[5],top[6]
        sw=l+s;n=g*sw
        adj=[[] for _ in range(n)]
        def lid(gr,x):return gr*sw+x
        def sid(gr,x):return gr*sw+l+x
        for gr in range(g):
            for lf in range(l):
                for sp in range(s):
                    u=lid(gr,lf);v=sid(gr,sp);adj[u].append(v);adj[v].append(u)
        if dense:
            for i in range(g):
                for j in range(i+1,g):
                    for sp in range(s):
                        u=sid(i,sp);v=sid(j,sp);adj[u].append(v);adj[v].append(u)
        else:
            for i in range(g):
                for j in range(i+1,g):
                    delta=j-i
                    u=sid(i,(delta-1)//h);v=sid(j,(g-delta-1)//h)
                    adj[u].append(v);adj[v].append(u)
        leaves=[lid(gr,lf) for gr in range(g) for lf in range(l)]
        alld=[bfs(adj,x) for x in range(n)]
        pairs=[];dom=[]
        for src in leaves:
            for dst in leaves:
                if src==dst:continue
                D=alld[src][dst]
                fp={x for x in range(n) if alld[src][x]+alld[dst][x]==D}
                pairs.append((src,dst,fp))
                if scope=='group':dom.append(src//sw)
                else:dom.append((src//sw)*l + (src%sw))
        return n,pairs,dom
    raise Exception(mode)

configs=[
 ['clos',4,'tor',1],['clos',4,'pod',1],['clos',6,'tor',0],
 ['leaf-spine',2,1],['leaf-spine',4,3],['leaf-spine',7,2],
 ['torus2d',3,'host'],['torus2d',3,'row'],['torus2d',4,'host'],['torus2d',5,'row'],
 ['torus3d',3,'host'],['torus3d',3,'line'],
 ['dragonfly',2,1,1,'router'],['dragonfly',4,1,3,'group'],['dragonfly',5,2,2,'target'],
 ['dragonfly-plus',2,2,2,1,1,'tor'],
 ['dragonfly-plus',3,2,1,2,0,'group'],
 ['dragonfly-plus',4,1,3,1,0,'tor'],
]
# only <=16 sessions; run each individually

def test(top):
    n,pairs,dom=topo(top)
    m=len(pairs)
    if m>1500:
        ids=random.Random(123).sample(range(m),min(500,m))
    else:ids=list(range(m))
    # one active group per selected template, plus inactive group at end
    ng=len(ids)+1
    groups=[];tasks=[]
    rnd=random.Random(999)
    for j,t in enumerate(ids):
        quota=rnd.randint(1,3)
        groups.append([quota,1])
        tasks.append([t,j,1,rnd.randint(0,7),rnd.randint(0,1)])
    groups.append([0,1])
    caps=[10**9]*n
    q={'groups':list(range(ng)),'nodes':list(range(n)),'tasks':list(range(len(tasks)))}
    sess={'topology':top,'caps':caps,'groups':groups,'tasks':tasks,'query':q,'transactions':[]}
    req={'version':2,'sessions':[sess]}
    data=entry.transport(req)
    p=subprocess.run(['/workspace/tmp/unit-merge-build/engine'],input=data,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    if p.returncode!=0:
        print('ENGINE FAIL',top,p.stderr.decode()[:500]);return False
    got=json.loads(p.stdout)['sessions'][0]
    if got['nodes']!=n or got['templates']!=m:
        print('COUNT MISMATCH',top,got['nodes'],got['templates'],n,m);return False
    usage=[0]*n
    for j,t in enumerate(ids):
        src,dst,fp=pairs[t]
        for x in fp:usage[x]+=groups[j][0]
    exp_tot=[len(ids),sum(usage),len(tasks),sum(t[4] for t in tasks)]
    if got['initial']['totals']!=exp_tot:
        print('TOTAL MISMATCH',top,got['initial']['totals'],exp_tot);return False
    for j,t in enumerate(ids):
        src,dst,fp=pairs[t]
        row=got['initial']['groups'][j]
        er=[j,1,1,groups[j][0],1,len(fp),dom[t],tasks[j][3]]
        if row!=er:
            print('GROUP MISMATCH',top,'template',t,'pair',src,dst,'got',row,'exp',er,'fp',sorted(fp));return False
    erow=got['initial']['groups'][-1]
    if erow!=[ng-1,0,0,0,1,0,-1,-1]:
        print('EMPTY MISMATCH',top,erow);return False
    for i,x in enumerate(usage):
        if got['initial']['nodes'][i]!=[i,x,10**9]:
            print('NODE MISMATCH',top,i,got['initial']['nodes'][i],[i,x,10**9]);return False
    for j,t in enumerate(tasks):
        row=got['initial']['tasks'][j]
        er=[j,j,t[0],1,t[3],t[4]]
        if row!=er:
            print('TASK MISMATCH',top,j,row,er);return False
    print('OK',top,'n',n,'m',m)
    return True

for c in configs:
    if not test(c):sys.exit(1)
print('ALL TOPO OK')
